// Parse YouTube RSS XML feed and extract recent videos
const xml = $input.first().json.data;

const entries = [];
const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
let match;

while ((match = entryRegex.exec(xml)) !== null) {
  const entry = match[1];
  const title = entry.match(/<title>([\s\S]*?)<\/title>/)?.[1] || '';
  const videoId = entry.match(/<yt:videoId>([\s\S]*?)<\/yt:videoId>/)?.[1] || '';
  const published = entry.match(/<published>([\s\S]*?)<\/published>/)?.[1] || '';
  const description = entry.match(/<media:description>([\s\S]*?)<\/media:description>/)?.[1] || '';
  const thumbnail = entry.match(/<media:thumbnail url="(.*?)"/)?.[1] || '';

  entries.push({
    title,
    videoId,
    url: 'https://www.youtube.com/watch?v=' + videoId,
    published,
    description: description.substring(0, 300),
    thumbnail
  });
}

const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const recentEntries = entries.filter(e => new Date(e.published) > oneWeekAgo);

return [{
  json: {
    videos: recentEntries,
    videoCount: recentEntries.length,
    weekOf: new Date().toISOString().split('T')[0]
  }
}];

